// Build minimal payload - W4 will fetch 3-manifest itself
return orders4.map(order => {
  // Normalize shipping address (handles JSON strings, field name variations, etc.)
  const rawShipping = order.shipping_address;
  let shippingAddress = normalizeShippingAddress(rawShipping);
  // Final fallback: ensure address_line_1 exists (D2C uses address_line1)
  if (shippingAddress && !shippingAddress.address_line_1) {
    shippingAddress.address_line_1 = shippingAddress.address_line1 || shippingAddress.address || '';
  }

  // Clean phone number (strip extensions) and ensure phone_number exists
  const rawPhone = shippingAddress?.phone_number || 
                   shippingAddress?.phone;
  const cleanedPhone = cleanPhoneNumber(rawPhone);

  // Use cleaned phone if available, otherwise use company fallback
  // Company fallback: 678-478-3477 (for non-Amazon orders)
  const phone_number = cleanedPhone || '+1-678-478-3477';

  // Add phone_number to shipping address if we have one
  if (shippingAddress) {
    shippingAddress.phone_number = phone_number;
    // Also ensure phone field exists for backward compatibility
    if (!shippingAddress.phone) {
      shippingAddress.phone = phone_number;
