  try {
    const res = await this.helpers.request({
      method: 'GET',
      uri: endpoint,
      qs: { key: ref.key, bucket: 'little-hero-orders', expiresIn: ttl },
      headers: {
        Authorization: `Bearer ${token}`,
        'Content-Type': 'application/json',
      },
      json: true,
    });

    const oneManifestUrl = res.url || res.data?.url || res.json?.url || res.result?.url;
    if (!oneManifestUrl) {
      throw new Error('Signed URL endpoint did not return a URL');
    }

    output.push({
      json: {
        ...item,
        oneManifestKey: ref.key,
        oneManifestUrl,
      },
    });
  } catch (error) {
    const status = error.response?.status || error.status || 'unknown';
    const details = error.response?.data ? JSON.stringify(error.response.data) : error.message;

    if (status === 401) {
      throw new Error('Authentication failed (401). Check BACKEND_API_TOKEN alignment between n8n and backend.');
    }

    throw new Error(`Get Signed URL (1-manifest)-W4 failed for key=${ref.key} (raw=${ref.raw}) status=${status}: ${details}`);
  }
}

return output;

